using UnityEngine;using UnityEditor;using System;using System.Linq;using System.Text;using System.IO;
public static class ValidatePickups{public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");var report=new StringBuilder();foreach(var source in UnityEngine.Object.FindObjectsByType<PickupController>(FindObjectsSortMode.None)){GameObject floor=null,copy=null,riderObject=null,wall=null;int n=0;void Check(bool ok,string msg){if(!ok)throw new Exception(source.name+": "+msg);n++;}try{
 floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(10000,-.5f,10000);floor.transform.localScale=new Vector3(200,1,200);copy=UnityEngine.Object.Instantiate(source.gameObject,new Vector3(10000,.02f,10000),Quaternion.identity);var pickup=copy.GetComponent<PickupController>();var engine=copy.GetComponent<MotorollerController>();var bike=engine.Movement;riderObject=new GameObject("Pickup rider test");riderObject.SetActive(false);var cam=new GameObject("Camera").AddComponent<Camera>();cam.enabled=false;cam.transform.SetParent(riderObject.transform,false);cam.transform.localPosition=Vector3.up*1.4f;var cc=riderObject.AddComponent<CharacterController>();cc.height=1.8f;cc.radius=.3f;cc.center=Vector3.up*.9f;var player=riderObject.AddComponent<PlayerController>();player.characterCamera=cam;player.characterController=cc;player.enabled=false;var rider=riderObject.AddComponent<PlayerBicycleInteraction>();rider.player=player;riderObject.transform.position=copy.transform.position+Vector3.left*2.3f;riderObject.transform.rotation=Quaternion.Euler(0,90,0);riderObject.SetActive(true);Physics.SyncTransforms();rider.Tick(true);Check(rider.bicycle==bike,"Aim selects pickup");Check(rider.TryMount(),"Mount");Check(!cc.enabled&&cam.transform.parent==bike.riderView,"Camera and walking transfer");var axle=bike.frontWheel.localPosition;for(int i=0;i<60;i++)rider.DriveRiding(0,1,true,false,.02f);pickup.RefreshWheels();Check(bike.CurrentSteeringAngle>25,"Steering reaches lock");Check(Vector3.Distance(axle,bike.frontWheel.localPosition)<.001f,"Centered wheel pivot");Check(Quaternion.Angle(pickup.frontRightSteering.localRotation,bike.steering.localRotation)<.01f,"Both front wheels steer");for(int i=0;i<100;i++)rider.DriveRiding(0,0,true,false,.02f);var rest=bike.frontWheel.localRotation;
 for(int i=0;i<300;i++)rider.DriveRiding(1,0,false,true,.02f);pickup.RefreshWheels();Check(copy.transform.position.z>10015,"Forward travel");Check(bike.Speed>bike.maximumSpeed-.1f,"Engine reaches maximum speed");Check(!rider.IsBoosting,"No pedal boost");Check(Quaternion.Angle(rest,bike.frontWheel.localRotation)>1,"Wheel spin");Check(Quaternion.Angle(pickup.rearRightWheel.localRotation,bike.rearWheel.localRotation)<.01f,"Rear wheels synchronized");for(int i=0;i<150;i++)rider.DriveRiding(0,0,true,false,.02f);Check(bike.Speed==0,"Brakes");var start=copy.transform.position;for(int i=0;i<100;i++)rider.DriveRiding(-1,0,false,false,.02f);Check(copy.transform.position.z<start.z-1,"Reverse");for(int i=0;i<100;i++)rider.DriveRiding(0,0,true,false,.02f);Check(rider.TryDismount(),"Safe side exit");Check(cc.enabled&&cam.transform.parent==riderObject.transform,"Restore walking and camera");
 var motor=copy.GetComponent<CharacterController>();motor.enabled=false;copy.transform.SetPositionAndRotation(new Vector3(10000,.02f,10000),Quaternion.identity);motor.enabled=true;bike.SetRidden(true);wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=new Vector3(10000,2.5f,10010);wall.transform.localScale=new Vector3(15,5,.2f);Physics.SyncTransforms();for(int i=0;i<400;i++){engine.Drive(1,0,false,.02f);Physics.SyncTransforms();}using(var so=new SerializedObject(engine)){float nose=(so.FindProperty("collisionCenter").vector3Value.z+so.FindProperty("collisionHalfExtents").vector3Value.z)*copy.transform.lossyScale.z;Check(copy.transform.position.z+nose<10009.92f&&copy.transform.position.z>10002,"Nose stops before real wall");}Check(copy.transform.position.y>-.1f&&copy.transform.position.y<.1f,"Ground support");report.AppendLine(source.name+": PASS "+n+" checks");
 }finally{if(riderObject){var r=riderObject.GetComponent<PlayerBicycleInteraction>();if(r&&r.IsRiding)r.TryDismount();UnityEngine.Object.DestroyImmediate(riderObject);}if(copy)UnityEngine.Object.DestroyImmediate(copy);if(wall)UnityEngine.Object.DestroyImmediate(wall);if(floor)UnityEngine.Object.DestroyImmediate(floor);}}
 File.WriteAllText("output/Pickups/validation.txt",report.ToString());return report.ToString();}}
